-- Generated from the shared journal trigger builder; Node keeps its TEMP activation.
-- D1 activates this journal only within one atomic batch.
CREATE TRIGGER brew_action_guard BEFORE INSERT ON settings WHEN NEW.key='brew_active_action' BEGIN
  SELECT CASE WHEN json_extract(NEW.value,'$.authorized') IS NOT 1 THEN RAISE(ABORT,'BREW_ACTION_FORBIDDEN') END;
  SELECT CASE WHEN json_extract(NEW.value,'$.valid') IS NOT 1 THEN RAISE(ABORT,'BREW_ACTION_CONFLICT') END;
END;

